from pathlib import Path

BASE = Path('.github/scripts/repair_playback_v7.py').read_text(encoding='utf-8')
exec(compile(BASE, 'repair_playback_v7_embedded.py', 'exec'), {})

APP = Path('app.js')
s = APP.read_text(encoding='utf-8')

# YouTube PLAYING/PAUSED callbacks can also be generated by ads,
# buffering and player lifecycle changes. They are observations only;
# they are not room commands.
start_marker = '''if (\n                    data === YT.PlayerState.PLAYING ||\n                    data === YT.PlayerState.PAUSED'''
end_marker = '''                  if (data === YT.PlayerState.ENDED) {'''

start = s.find(start_marker)
end = s.find(end_marker, start + len(start_marker)) if start >= 0 else -1
if start < 0 or end < 0:
    raise SystemExit('YouTube PLAYING/PAUSED callback block not found')

new_state_branch = '''if (\n                    data === YT.PlayerState.PLAYING ||\n                    data === YT.PlayerState.PAUSED\n                  ) {\n                    state.playbackLastPlayerState =\n                      data === YT.PlayerState.PLAYING\n                        ? "playing"\n                        : "paused";\n\n                    state.playbackLastObservedPosition =\n                      await asyncCurrentPosition().catch(() => null);\n\n                    // Do not write Firebase from YouTube state callbacks.\n                    // Explicit WatchTogether controls are the only source\n                    // of room playback commands.\n                    return;\n                  }\n\n'''
s = s[:start] + new_state_branch + s[end:]

# When a playing participant suddenly reports a large backward jump,
# temporarily treat it as a transient/ad state. Release the guard as soon
# as the local content position catches the shared timeline.
old_ad = '''if (timeline.playing === true && Number.isFinite(previousObserved) &&\n        position < previousObserved - 3 &&\n        now - Number(state.playbackLocalIntentAt || 0) > 1200) {\n      state.playbackAdGuardUntil = Date.now() + 7500;\n      state.playbackTransientStateUntil = Date.now() + 7500;\n      state.playbackLastObservedPosition = position;\n      return;\n    }'''

new_ad = '''if (\n      timeline.playing === true &&\n      Number.isFinite(previousObserved) &&\n      position < previousObserved - 3 &&\n      now - Number(state.playbackLocalIntentAt || 0) > 1200\n    ) {\n      state.playbackAdGuardUntil = Date.now() + 3000;\n      state.playbackTransientStateUntil = Date.now() + 3000;\n      state.playbackLastObservedPosition = position;\n      return;\n    }\n\n    if (\n      Number(state.playbackAdGuardUntil || 0) > Date.now() &&\n      Math.abs(position - expected) <= 3.0\n    ) {\n      state.playbackAdGuardUntil = 0;\n      state.playbackTransientStateUntil = 0;\n    }'''

if old_ad not in s:
    raise SystemExit('ad protection block not found')
s = s.replace(old_ad, new_ad, 1)

s = s.replace('SHARED ROOM TIMELINE PLAYBACK SYNC V6', 'SHARED ROOM TIMELINE PLAYBACK SYNC V8', 1)
APP.write_text(s, encoding='utf-8')
